ruleToc.chapterList:
@js:
var data = JSON.parse(src);
var vod = data.list[0];
var playUrl = vod.vod_play_url || '';
var lines = playUrl.split('$$$');
var m3u8Line = lines.length > 1 ? lines[1] : lines[0];
var eps = m3u8Line.split('#');
var list = [];
for (var i = 0; i < eps.length; i++) {
  var idx = eps[i].indexOf('$');
  if (idx > 0) {
    list.push({
      text: eps[i].substring(0, idx),
      href: eps[i].substring(idx + 1)
    });
  }
}
list

